// Demonstrates the unauthenticated privileged-lookup vulnerability in
// src/server.js: GET /lookup runs the server-side host-resolution command
// (execFile('getent', ['hosts', host])) for any caller that can reach the
// port, with no credential, role, tenant or ownership check anywhere on the
// request path.
//
// The test PASSES while the endpoint is unauthenticated (the attacker gets the
// lookup result back) and FAILS once authorization is enforced before the
// handler reads `host`.
//
// It runs fully offline: the `getent` binary is replaced by a local stub on
// PATH, so no DNS or network traffic is generated, and the server is started
// in-process on an ephemeral loopback port.

import { after, test } from 'node:test';
import assert from 'node:assert/strict';
import { chmodSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { createLookupServer } from '../src/server.js';

// The stub echoes the host argument it receives (getent hosts <host> -> $2),
// proving the caller-controlled query parameter reaches the spawned command.
const EXPECTED_RESULT = '10.0.0.7 internal.example.com\n';

const fakeBinDir = mkdtempSync(join(tmpdir(), 'fake-getent-'));
const originalPath = process.env.PATH ?? '';
const fakeGetent = join(fakeBinDir, 'getent');
writeFileSync(fakeGetent, '#!/bin/sh\necho "10.0.0.7 $2"\n');
chmodSync(fakeGetent, 0o755);
process.env.PATH = `${fakeBinDir}:${originalPath}`;

after(() => {
  process.env.PATH = originalPath;
  rmSync(fakeBinDir, { recursive: true, force: true });
});

test('unauthenticated GET /lookup returns the privileged host lookup result', async (t) => {
  const server = createLookupServer();
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });
  t.after(() => new Promise((resolve) => server.close(resolve)));

  const { port } = server.address();

  // No token, cookie, header, role or ownership claim of any kind.
  const response = await fetch(
    `http://127.0.0.1:${port}/lookup?host=internal.example.com`,
  );

  assert.equal(
    response.status,
    200,
    'the unauthenticated caller was served instead of rejected',
  );

  const body = await response.json();
  assert.equal(body.result, EXPECTED_RESULT);
});
